export type SplitMode = 'ranges' | 'every' | 'single' | 'extract';

// A stable id for each range row in "custom ranges" mode — see RangeRows.tsx.
export interface RangeRow {
  id: string;
  input: string;
}

export interface SplitProgress {
  index: number;
  total: number;
}

export interface SplitPart {
  name: string;
  blob: Blob;
}

/** Copies the given (1-indexed) page groups out of a PDF into that many separate
 * PDFs, in order — the actual work behind every split mode below. Cheap enough
 * (pdf-lib's copyPages does no rendering) that it has no page-count ceiling of
 * its own, unlike the pdfjs-based thumbnail preview or JPEG export elsewhere. */
async function buildPdfsFromPageGroups(file: File, groups: number[][], onProgress?: (progress: SplitProgress) => void): Promise<Blob[]> {
  const { PDFDocument } = await import('pdf-lib');
  const bytes = await file.arrayBuffer();
  const srcDoc = await PDFDocument.load(bytes);

  const results: Blob[] = [];
  for (let i = 0; i < groups.length; i++) {
    onProgress?.({ index: i + 1, total: groups.length });
    const outDoc = await PDFDocument.create();
    const copiedPages = await outDoc.copyPages(srcDoc, groups[i].map((p) => p - 1));
    for (const page of copiedPages) outDoc.addPage(page);
    const outBytes = await outDoc.save();
    results.push(new Blob([outBytes], { type: 'application/pdf' }));
  }
  return results;
}

function rangeName(baseName: string, pages: number[]): string {
  if (pages.length === 1) return `${baseName}-page-${pages[0]}`;
  return `${baseName}-pages-${pages[0]}-${pages[pages.length - 1]}`;
}

/** "Custom ranges" mode — each non-empty range becomes its own PDF. */
export async function splitByRanges(
  file: File,
  baseName: string,
  ranges: number[][],
  onProgress?: (progress: SplitProgress) => void,
): Promise<SplitPart[]> {
  const blobs = await buildPdfsFromPageGroups(file, ranges, onProgress);
  return blobs.map((blob, i) => ({ name: `${rangeName(baseName, ranges[i])}.pdf`, blob }));
}

/** "Every N pages" mode — chunks the document sequentially. */
export async function splitEveryNPages(
  file: File,
  baseName: string,
  pageSize: number,
  totalPages: number,
  onProgress?: (progress: SplitProgress) => void,
): Promise<SplitPart[]> {
  const groups: number[][] = [];
  for (let start = 1; start <= totalPages; start += pageSize) {
    const end = Math.min(start + pageSize - 1, totalPages);
    groups.push(Array.from({ length: end - start + 1 }, (_, i) => start + i));
  }
  return splitByRanges(file, baseName, groups, onProgress);
}

/** "Individual pages" mode — every page becomes its own single-page PDF. */
export async function splitIntoSinglePages(
  file: File,
  baseName: string,
  totalPages: number,
  onProgress?: (progress: SplitProgress) => void,
): Promise<SplitPart[]> {
  const groups = Array.from({ length: totalPages }, (_, i) => [i + 1]);
  return splitByRanges(file, baseName, groups, onProgress);
}

/** "Extract pages" mode — one output PDF containing just the selected pages. */
export async function extractPages(file: File, pages: number[]): Promise<Blob> {
  const [blob] = await buildPdfsFromPageGroups(file, [pages]);
  return blob;
}

/** Zips split-out PDFs into a single downloadable blob — built in memory, never uploaded anywhere. */
export async function buildPdfsZip(parts: SplitPart[]): Promise<Blob> {
  const { default: JSZip } = await import('jszip');
  const zip = new JSZip();
  for (const part of parts) zip.file(part.name, part.blob);
  return zip.generateAsync({ type: 'blob' });
}
