import type { FC } from 'react';
import { Download, Scissors } from 'lucide-react';
import { formatBytes } from '@/lib/image/convert';
import type { SplitMode } from '@/lib/pdf/split';

interface ConversionResultProps {
  hasFile: boolean;
  mode: SplitMode;
  outputBlob: Blob | null;
  partCount: number;
  fileName: string;
  progress: { index: number; total: number } | null;
  isZipping: boolean;
  error: string | null;
  canGenerate: boolean;
  onGenerate: () => void;
}

const MODE_ACTION_LABEL: Record<SplitMode, string> = {
  ranges: 'Split into files',
  every: 'Split PDF',
  single: 'Split into pages',
  extract: 'Extract pages',
};

// Generation is explicit (a button), not reactive to every settings tweak —
// re-splitting is real work, so it only runs once the user asks for it.
const ConversionResult: FC<ConversionResultProps> = ({
  hasFile,
  mode,
  outputBlob,
  partCount,
  fileName,
  progress,
  isZipping,
  error,
  canGenerate,
  onGenerate,
}) => {
  const handleDownload = () => {
    if (!outputBlob) return;
    const url = URL.createObjectURL(outputBlob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  if (error) {
    return (
      <div className="glass-panel p-6 space-y-3">
        <p className="text-sm text-destructive" role="alert">
          {error}
        </p>
        <button
          type="button"
          onClick={onGenerate}
          disabled={!canGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          <Scissors className="w-4 h-4" />
          Try again
        </button>
      </div>
    );
  }

  if (isZipping) {
    return (
      <div className="glass-panel p-6 flex items-center gap-3" role="status" aria-live="polite">
        <div className="w-4 h-4 rounded-full border-2 border-accent border-t-transparent animate-spin shrink-0" />
        <p className="text-sm text-muted-foreground">Zipping files…</p>
      </div>
    );
  }

  if (progress) {
    const pct = Math.round((progress.index / progress.total) * 100);
    return (
      <div className="glass-panel p-6 space-y-3" role="status" aria-live="polite">
        <p className="text-sm text-muted-foreground">
          Creating file {progress.index} of {progress.total}…
        </p>
        <div className="h-1.5 rounded-full bg-border overflow-hidden">
          <div className="h-full bg-accent transition-all duration-200" style={{ width: `${pct}%` }} />
        </div>
      </div>
    );
  }

  if (!hasFile) return null;

  if (!outputBlob) {
    return (
      <div className="glass-panel p-6 flex items-center justify-between gap-4 flex-wrap">
        <p className="text-sm text-muted-foreground">Ready when you are.</p>
        <button
          type="button"
          onClick={onGenerate}
          disabled={!canGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          <Scissors className="w-4 h-4" />
          {MODE_ACTION_LABEL[mode]}
        </button>
      </div>
    );
  }

  const summary =
    mode === 'extract'
      ? `${formatBytes(outputBlob.size)} PDF extracted`
      : `${partCount} ${partCount === 1 ? 'file' : 'files'} · ${formatBytes(outputBlob.size)} ZIP`;

  return (
    <div className="glass-panel hover:border-border p-4 md:p-6 flex items-center justify-between gap-4 flex-wrap">
      <p className="text-sm font-medium text-foreground">{summary}</p>
      <button
        type="button"
        onClick={handleDownload}
        className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors"
      >
        <Download className="w-4 h-4" />
        {mode === 'extract' ? 'Download PDF' : 'Download ZIP'}
      </button>
    </div>
  );
};

export default ConversionResult;
