import type { FC } from 'react';
import { useEffect, useMemo, useState } from 'react';
import ToolLayout from '@/components/tools/ToolLayout';
import PillGroup from '@/components/tools/PillGroup';
import PdfPreviewDialog from '@/components/tools/PdfPreviewDialog';
import { Input } from '@/components/ui/input';
import UploadBox from '@/components/tools/pdf-to-jpg/UploadBox';
import PageThumbnails from '@/components/tools/split-pdf/PageThumbnails';
import RangeRows from '@/components/tools/split-pdf/RangeRows';
import ConversionResult from '@/components/tools/split-pdf/ConversionResult';
import { usePersistentState } from '@/hooks/usePersistentState';
import { useDebouncedValue } from '@/hooks/useDebouncedValue';
import { getPdfPageCount, parsePageRange } from '@/lib/pdf/convert';
import {
  splitByRanges,
  splitEveryNPages,
  splitIntoSinglePages,
  extractPages,
  buildPdfsZip,
  type SplitMode,
  type RangeRow,
  type SplitProgress,
} from '@/lib/pdf/split';

const MODE_OPTIONS: { value: SplitMode; label: string }[] = [
  { value: 'ranges', label: 'Custom Ranges' },
  { value: 'every', label: 'Every N Pages' },
  { value: 'single', label: 'Individual Pages' },
  { value: 'extract', label: 'Extract Pages' },
];

const SplitPdf: FC = () => {
  const [file, setFile] = usePersistentState<File | null>('split-pdf:file', null);
  const [mode, setMode] = usePersistentState<SplitMode>('split-pdf:mode', 'ranges');
  const [rangeRows, setRangeRows] = usePersistentState<RangeRow[]>('split-pdf:rangeRows', [{ id: crypto.randomUUID(), input: '' }]);
  const [everyN, setEveryN] = usePersistentState<number>('split-pdf:everyN', 1);
  const [extractInput, setExtractInput] = usePersistentState<string>('split-pdf:extractInput', '');

  const [totalPages, setTotalPages] = useState<number | null>(null);
  const [outputBlob, setOutputBlob] = useState<Blob | null>(null);
  const [partCount, setPartCount] = useState(0);
  const [progress, setProgress] = useState<SplitProgress | null>(null);
  const [isZipping, setIsZipping] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [previewPage, setPreviewPage] = useState<number | null>(null);

  const debouncedExtractInput = useDebouncedValue(extractInput, 300);

  // Page count is cheap to read (no rendering) — fetch it as soon as a file is
  // picked so the range/count fields below can validate against it right away.
  useEffect(() => {
    let ignore = false;

    setTotalPages(null);
    setOutputBlob(null);
    setPartCount(0);
    setProgress(null);
    setIsZipping(false);
    setError(null);

    if (!file) return;

    getPdfPageCount(file)
      .then((count) => {
        if (!ignore) setTotalPages(count);
      })
      .catch((err: Error) => {
        if (!ignore) setError(err.message || "This file couldn't be read as a PDF");
      });

    return () => {
      ignore = true;
    };
  }, [file]);

  // A generated result only reflects the mode/settings at the moment it was
  // built — invalidate it (not regenerate) whenever any of that changes, the
  // same explicit-generate convention as every other PDF tool here.
  useEffect(() => {
    setOutputBlob(null);
    setPartCount(0);
    setError(null);
  }, [mode, rangeRows, everyN, debouncedExtractInput]);

  const highlightedPages = useMemo(() => {
    if (totalPages === null) return undefined;
    if (mode === 'extract') {
      const trimmed = debouncedExtractInput.trim();
      return trimmed === '' ? new Set<number>() : new Set(parsePageRange(trimmed, totalPages));
    }
    if (mode === 'ranges') {
      const pages = new Set<number>();
      rangeRows.forEach((row) => parsePageRange(row.input, totalPages).forEach((p) => pages.add(p)));
      return pages;
    }
    return undefined; // "every"/"single" always include every page — nothing to dim
  }, [mode, debouncedExtractInput, rangeRows, totalPages]);

  const canGenerate = (() => {
    if (!file || totalPages === null || totalPages === 0) return false;
    if (mode === 'extract') return parsePageRange(debouncedExtractInput, totalPages).length > 0;
    if (mode === 'ranges') return rangeRows.some((row) => parsePageRange(row.input, totalPages).length > 0);
    if (mode === 'every') return everyN >= 1;
    return true; // "single"
  })();

  const handleGenerate = () => {
    if (!file || totalPages === null || !canGenerate) return;
    setError(null);
    setOutputBlob(null);

    const baseName = file.name.replace(/\.pdf$/i, '') || 'document';

    const run = async () => {
      if (mode === 'extract') {
        const pages = parsePageRange(debouncedExtractInput, totalPages);
        setProgress({ index: 1, total: 1 });
        const blob = await extractPages(file, pages);
        setProgress(null);
        setOutputBlob(blob);
        setPartCount(1);
        return;
      }

      let parts;
      if (mode === 'ranges') {
        const groups = rangeRows.map((row) => parsePageRange(row.input, totalPages)).filter((g) => g.length > 0);
        parts = await splitByRanges(file, baseName, groups, setProgress);
      } else if (mode === 'every') {
        parts = await splitEveryNPages(file, baseName, Math.max(1, everyN), totalPages, setProgress);
      } else {
        parts = await splitIntoSinglePages(file, baseName, totalPages, setProgress);
      }

      setProgress(null);
      setIsZipping(true);
      const zip = await buildPdfsZip(parts);
      setIsZipping(false);
      setOutputBlob(zip);
      setPartCount(parts.length);
    };

    run().catch((err: Error) => {
      setError(err.message || "This PDF couldn't be split");
      setProgress(null);
      setIsZipping(false);
    });
  };

  const fileBaseName = file ? file.name.replace(/\.pdf$/i, '') || 'document' : 'document';
  const outputFileName = mode === 'extract' ? `${fileBaseName}-extracted.pdf` : `${fileBaseName}-split.zip`;

  return (
    <ToolLayout
      title="Split PDF"
      description="Break a PDF into pieces — custom ranges, fixed-size chunks, single pages, or just extract a few — entirely in your browser."
    >
      <div className="max-w-2xl space-y-6">
        <UploadBox file={file} onSelect={setFile} onClear={() => setFile(null)} />

        {file && (
          <>
            <div>
              <h2 className="text-sm font-medium text-muted-foreground mb-3">How to split</h2>
              <PillGroup aria-label="Split mode" options={MODE_OPTIONS} value={mode} onChange={setMode} />
            </div>

            {totalPages !== null && (
              <div>
                <h2 className="text-sm font-medium text-muted-foreground mb-3">
                  Pages <span className="text-muted-foreground/60">({totalPages} total)</span>
                </h2>
                <PageThumbnails
                  file={file}
                  totalPages={totalPages}
                  highlightedPages={highlightedPages}
                  onPageClick={setPreviewPage}
                />
              </div>
            )}

            {mode === 'ranges' && (
              <div>
                <h2 className="text-sm font-medium text-muted-foreground mb-3">Output files</h2>
                <RangeRows rows={rangeRows} totalPages={totalPages ?? 0} onChange={setRangeRows} />
              </div>
            )}

            {mode === 'every' && (
              <div>
                <h2 className="text-sm font-medium text-muted-foreground mb-3">Pages per file</h2>
                <Input
                  type="number"
                  min={1}
                  max={totalPages ?? undefined}
                  value={everyN}
                  onChange={(e) => setEveryN(Math.max(1, Math.round(Number(e.target.value) || 1)))}
                  aria-label="Pages per file"
                  className="w-28"
                />
                {totalPages !== null && (
                  <p className="text-xs text-muted-foreground mt-2">
                    Will produce {Math.ceil(totalPages / Math.max(1, everyN))} files.
                  </p>
                )}
              </div>
            )}

            {mode === 'extract' && (
              <div>
                <h2 className="text-sm font-medium text-muted-foreground mb-3">Pages to extract</h2>
                <Input
                  type="text"
                  value={extractInput}
                  onChange={(e) => setExtractInput(e.target.value)}
                  placeholder="e.g. 1-3, 5, 8-10"
                  aria-label="Pages to extract"
                />
              </div>
            )}

            {mode === 'single' && totalPages !== null && (
              <p className="text-sm text-muted-foreground">Will produce {totalPages} single-page PDFs, zipped together.</p>
            )}

            <ConversionResult
              hasFile={!!file}
              mode={mode}
              outputBlob={outputBlob}
              partCount={partCount}
              fileName={outputFileName}
              progress={progress}
              isZipping={isZipping}
              error={error}
              canGenerate={canGenerate}
              onGenerate={handleGenerate}
            />
          </>
        )}
      </div>

      <PdfPreviewDialog
        open={previewPage !== null}
        file={file}
        fileName={file?.name ?? ''}
        pageCount={totalPages}
        initialPage={previewPage ?? undefined}
        onClose={() => setPreviewPage(null)}
      />
    </ToolLayout>
  );
};

export default SplitPdf;
