import type { FC } from 'react';
import { Plus, X } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { parsePageRange } from '@/lib/pdf/convert';
import type { RangeRow } from '@/lib/pdf/split';

interface RangeRowsProps {
  rows: RangeRow[];
  totalPages: number;
  onChange: (rows: RangeRow[]) => void;
}

// One row per output file in "Custom ranges" mode — add/remove freely, each
// row becomes its own PDF in the resulting ZIP.
const RangeRows: FC<RangeRowsProps> = ({ rows, totalPages, onChange }) => {
  const handleInputChange = (id: string, value: string) => {
    onChange(rows.map((row) => (row.id === id ? { ...row, input: value } : row)));
  };

  const handleAdd = () => onChange([...rows, { id: crypto.randomUUID(), input: '' }]);

  const handleRemove = (id: string) => {
    if (rows.length <= 1) return;
    onChange(rows.filter((row) => row.id !== id));
  };

  return (
    <div className="space-y-2">
      {rows.map((row, index) => {
        const trimmed = row.input.trim();
        const isInvalid = trimmed !== '' && parsePageRange(trimmed, totalPages).length === 0;
        return (
          <div key={row.id} className="flex items-center gap-2">
            <span className="text-xs font-mono text-muted-foreground w-14 shrink-0">File {index + 1}</span>
            <Input
              type="text"
              value={row.input}
              onChange={(e) => handleInputChange(row.id, e.target.value)}
              placeholder="e.g. 1-3"
              aria-label={`Page range for output file ${index + 1}`}
              className={`h-9 text-sm ${isInvalid ? 'border-destructive focus-visible:ring-destructive' : ''}`}
            />
            <button
              type="button"
              onClick={() => handleRemove(row.id)}
              disabled={rows.length <= 1}
              aria-label={`Remove range ${index + 1}`}
              className="shrink-0 p-2 rounded-md text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors disabled:opacity-30 disabled:cursor-not-allowed disabled:hover:bg-transparent disabled:hover:text-muted-foreground"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        );
      })}

      <button
        type="button"
        onClick={handleAdd}
        className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium text-muted-foreground hover:text-foreground hover:bg-accent/5 transition-colors"
      >
        <Plus className="w-3.5 h-3.5" />
        Add another file
      </button>
    </div>
  );
};

export default RangeRows;
