import type { FC } from 'react';
import { useEffect, useState } from 'react';
import { Eye } from 'lucide-react';
import { convertPdfToImages, MAX_PAGES } from '@/lib/pdf/convert';

interface PageThumbnailsProps {
  file: File;
  totalPages: number;
  /** Pages to show at full opacity — everything else dims. Omit to show every
   * page at full opacity (e.g. modes where every page ends up in some output). */
  highlightedPages?: Set<number>;
  /** Opens the full-PDF preview dialog, scrolled to this page. */
  onPageClick: (pageNumber: number) => void;
}

// A visual reference for picking page numbers/ranges by eye — selection
// itself still happens via the range/count fields elsewhere on the page.
// Clicking a thumbnail opens the full-document preview dialog (same one
// Merge PDF uses) scrolled to that page, for a closer look.
const PageThumbnails: FC<PageThumbnailsProps> = ({ file, totalPages, highlightedPages, onPageClick }) => {
  const [thumbs, setThumbs] = useState<{ pageNumber: number; url: string }[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    if (totalPages > MAX_PAGES) {
      setIsLoading(false);
      setThumbs([]);
      return;
    }

    let ignore = false;
    const urls: string[] = [];
    setIsLoading(true);
    setFailed(false);

    convertPdfToImages(file, { scale: 0.35, quality: 55 })
      .then((pages) => {
        if (ignore) return;
        const next = pages.map((page) => {
          const url = URL.createObjectURL(page.blob);
          urls.push(url);
          return { pageNumber: page.pageNumber, url };
        });
        setThumbs(next);
        setIsLoading(false);
      })
      .catch(() => {
        if (!ignore) {
          setFailed(true);
          setIsLoading(false);
        }
      });

    return () => {
      ignore = true;
      urls.forEach((url) => URL.revokeObjectURL(url));
    };
  }, [file, totalPages]);

  if (totalPages > MAX_PAGES) {
    return (
      <p className="text-xs text-muted-foreground">
        Page previews aren't available for PDFs over {MAX_PAGES} pages — this one has {totalPages}. The range and page-count
        fields below still work.
      </p>
    );
  }

  if (isLoading) return <p className="text-xs text-muted-foreground">Loading page previews…</p>;
  if (failed || thumbs.length === 0) return null;

  return (
    <div className="grid grid-cols-4 sm:grid-cols-6 md:grid-cols-8 gap-2.5 max-h-80 overflow-y-auto p-1">
      {thumbs.map(({ pageNumber, url }) => {
        const isDimmed = highlightedPages !== undefined && !highlightedPages.has(pageNumber);
        return (
          <div key={pageNumber} className="flex flex-col items-center gap-1">
            <button
              type="button"
              onClick={() => onPageClick(pageNumber)}
              aria-label={`Preview page ${pageNumber}`}
              title="Click to preview the full PDF"
              className={`group relative w-full aspect-[3/4] rounded-md overflow-hidden border bg-background/50 transition-opacity ${
                isDimmed ? 'border-border/40 opacity-35' : 'border-border'
              }`}
            >
              <img src={url} alt={`Page ${pageNumber}`} className="w-full h-full object-cover" />
              <span className="absolute inset-0 flex items-center justify-center bg-black/0 group-hover:bg-black/50 transition-colors">
                <Eye className="w-3.5 h-3.5 text-white opacity-0 group-hover:opacity-100 transition-opacity" />
              </span>
            </button>
            <span className="text-[10px] font-mono text-muted-foreground">{pageNumber}</span>
          </div>
        );
      })}
    </div>
  );
};

export default PageThumbnails;
